// Package protocol is the single registry of the earbuds' command protocol:
// the opcode constants, the frame envelope (Block, Query, ParseBlocks) and the
// reference table of every known command (table.json, generated by
// scripts/gen_protocol.py from docs/reference/protocol.json).
package protocol

// Opcodes the daemon and the CLI use. Everything else in the device's command
// space lives only in the table (Lookup / ByName).
const (
	OpFind            byte = 0x05 // LED flash; "find" is a local tone, this is only mapped
	OpANCStrength     byte = 0x07 // legacy ANC strength, silent on the verified model
	OpGame            byte = 0x09 // game / low-latency mode
	OpSleep           byte = 0x10 // sleep mode
	OpFit             byte = 0x11 // ear-tip fit test
	OpAutoOff         byte = 0x14 // timed power-off
	OpBalance         byte = 0x16 // left/right balance
	OpANC             byte = 0x17 // ANC mode / scene / level
	OpPromptVolume    byte = 0x1D // prompt (tone) volume
	OpEQ              byte = 0x22 // multi-band EQ v2
	OpLDAC            byte = 0x23 // LDAC
	OpMultipoint      byte = 0x24 // multipoint
	OpWind            byte = 0x2A // wind-noise detection
	OpWear            byte = 0x2C // wear (in-ear) detection
	OpSpatial         byte = 0x2D // spatial audio
	OpBattery         byte = 0x2F // battery (command form)
	OpVersion         byte = 0x30 // version (command form)
	OpHearingMode     byte = 0x45 // hearing-test mode
	OpHearingLeft     byte = 0x46 // hearing curve, left ear
	OpHearingRight    byte = 0x47 // hearing curve, right ear
	OpWearSensitivity byte = 0x48 // wear-sensor sensitivity
	OpQuery           byte = 0xFE // query a cmdId: FF 03 FE 01 <id>
)

// SOF is the first byte of every frame.
const SOF byte = 0xFF

// ActionOpcodes maps the daemon's action names to the opcode each one writes.
// It is the only name -> opcode table of the write path.
var ActionOpcodes = map[string]byte{
	"anc": OpANC, "game": OpGame, "sleep": OpSleep, "ldac": OpLDAC,
	"multipoint": OpMultipoint, "wind": OpWind, "promptVol": OpPromptVolume,
	"autoOff": OpAutoOff, "wear": OpWear, "balance": OpBalance,
	"spatial": OpSpatial, "fit": OpFit, "wearSensitivity": OpWearSensitivity,
	"find": OpFind,
}

// ActionOpcode returns the opcode of a write action.
func ActionOpcode(action string) (byte, bool) {
	op, ok := ActionOpcodes[action]
	return op, ok
}
